/**
 * Consumer smoke app for @hakistack/i18n: authoring (`/engine`), codegen output (registry, TK, typed
 * directive) and the runtime (`provideI18n`, `translateSignal`) — with no @hakistack/ng-daisyui installed.
 * The `src/i18n/definitions/*` files are generated by `hakistack-i18n scan` before the build.
 */
import { ChangeDetectionStrategy, Component } from '@angular/core';
import { bootstrapApplication } from '@angular/platform-browser';
import { provideI18n, translateSignal } from '@hakistack/i18n';
import { AppTranslateDirective } from './i18n/definitions/appTranslate.directive';
import { ALL_TRANSLATIONS } from './i18n/definitions/index.generated';
import { TK } from './i18n/definitions/keys.generated';

@Component({
  selector: 'app-root',
  imports: [AppTranslateDirective],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <h1>{{ welcome() }}</h1>
    <p *appTranslate="let t">{{ t.home.farewell() }}</p>
  `,
})
class AppComponent {
  protected readonly welcome = translateSignal(TK.home.welcome);
}

bootstrapApplication(AppComponent, {
  providers: [
    provideI18n({
      registry: ALL_TRANSLATIONS,
      languages: [
        { id: 'en', label: 'English' },
        { id: 'es', label: 'Español' },
      ],
      defaultLang: 'es',
      fallbackLang: 'en',
    }),
  ],
}).catch((err) => console.error(err));
